 router.post('/:id/customer-return-lines/:lineId/receive',async(req,res)=>{let tx;try{
  if(!/^[1-9]\d*$/.test(req.params.id)||!/^[1-9]\d*$/.test(req.params.lineId))fail(400,'เลขรายการไม่ถูกต้อง');const b=req.body||{},location=String(b.receiptLocation||'');if(!location||location.length>50)fail(400,'เลือก Location รับคืนในโซน RCV');const pool=await poolPromise;tx=new sql.Transaction(pool);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);const q=()=>new sql.Request(tx);const item=(await q().input('L',sql.Int,req.params.lineId).input('D',sql.Int,req.params.id).query('SELECT l.*,r.ReturnId AS CustomerReturnId,r.ReturnNo,r.ReturnSentAt,d.DeliveryId AS DeliveryId,d.WhId,d.CategoryCode FROM dbWMS.dbo.CustomerDeliveryReturnLines l WITH(UPDLOCK,HOLDLOCK) JOIN dbWMS.dbo.CustomerDeliveryReturns r ON r.ReturnId=l.ReturnId JOIN dbWMS.dbo.DeliveryOrders d ON d.DeliveryId=r.DeliveryId WHERE l.ReturnLineId=@L AND d.DeliveryId=@D')).recordset[0];if(!item)fail(404,'ไม่พบรายการคืนสินค้า');if(!shipping.can(req,item.CategoryCode,'CONFIRM'))fail(403,'ไม่มีสิทธิ์รับสินค้าคืน');if(!item.ExpectedReturn||!item.ReturnSentAt)fail(409,'ต้องบันทึกส่งคืนจากลูกค้าก่อนรับเข้าคลัง');if(item.PhysicalReturned)fail(409,'รายการนี้รับเข้าคลังแล้ว');const receipt=(await q().input('Wh',sql.Int,item.WhId).input('Loc',sql.NVarChar(50),location).query("SELECT LocationCode FROM dbMaster.dbo.Locations WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND LocationCode=@Loc AND IsActive=1 AND UPPER(Zone)='RCV'")).recordset[0];if(!receipt)fail(400,`Location ${location} ไม่ใช่จุดรับคืน RCV`);const product=(await q().input('P',sql.Int,item.ProductId).query('SELECT Barcode FROM dbMaster.dbo.tblProducts WHERE ProductId=@P')).recordset[0],stock=(await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Loc',sql.NVarChar(50),location).query('SELECT StockId,Quantity FROM dbWMS.dbo.tblStock WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND ProductId=@P AND LocationCode=@Loc')).recordset[0],old=Number(stock?.Quantity||0),qty=Number(item.Quantity);if(stock)await q().input('S',sql.Int,stock.StockId).input('Q',sql.Decimal(18,2),qty).query('UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity+@Q,UpdatedAt=SYSDATETIME() WHERE StockId=@S');else await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Barcode',sql.NVarChar(50),product?.Barcode||null).input('Loc',sql.NVarChar(50),location).input('Q',sql.Decimal(18,2),qty).query('INSERT INTO dbWMS.dbo.tblStock(whid,ProductId,Barcode,LocationCode,Quantity) VALUES(@Wh,@P,@Barcode,@Loc,@Q)');await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Barcode',sql.NVarChar(50),product?.Barcode||null).input('Loc',sql.NVarChar(50),location).input('Q',sql.Decimal(18,2),qty).input('After',sql.Decimal(18,2),old+qty).input('Ref',sql.NVarChar(60),item.ReturnNo).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query("INSERT INTO dbWMS.dbo.tblStockTransactions(TransType,whid,ProductId,Barcode,LocationCode,QtyChange,QtyAfter,RefDocNo,Remark,CreatedBy,CreatedAt) VALUES(N'RETURN_IN',@Wh,@P,@Barcode,@Loc,@Q,@After,@Ref,N'รับคืนจากลูกค้าเข้าจุด RCV',@By,SYSDATETIME())");await q().input('L',sql.Int,item.ReturnLineId).input('Loc',sql.NVarChar(50),location).input('R',sql.Int,item.CustomerReturnId).query('UPDATE dbWMS.dbo.CustomerDeliveryReturnLines SET PhysicalReturned=1,ReceiptLocationCode=@Loc WHERE ReturnLineId=@L;UPDATE dbWMS.dbo.CustomerDeliveryReturns SET ReturnStatus=CASE WHEN NOT EXISTS(SELECT 1 FROM dbWMS.dbo.CustomerDeliveryReturnLines WHERE ReturnId=@R AND ExpectedReturn=1 AND PhysicalReturned=0) THEN \'RECEIVED\' ELSE \'PARTIALLY_RECEIVED\' END WHERE ReturnId=@R');await shipping.audit(q,item.DeliveryId,'CUSTOMER_RETURN_RECEIVE',req.user.username||req.user.id,{returnId:item.CustomerReturnId,returnNo:item.ReturnNo,returnLineId:item.ReturnLineId,productCode:item.ProductCode,quantity:qty,receiptLocation:location});await tx.commit();res.json({success:true,received:true});
 }catch(e){if(tx)try{await tx.rollback()}catch{}error(res,e)}});
 router.post('/:id/return-lines/:lineId/putaway',async(req,res)=>{let tx;try{
 if(!/^[1-9]\d*$/.test(req.params.id)||!/^[1-9]\d*$/.test(req.params.lineId))fail(400,'เลขรายการไม่ถูกต้อง');const b=req.body||{},destination=String(b.destinationLocation||'');if(!destination||destination.length>50)fail(400,'เลือก Location จัดเก็บ');
 const pool=await poolPromise;tx=new sql.Transaction(pool);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);const q=()=>new sql.Request(tx);const item=(await q().input('ReturnLine',sql.Int,req.params.lineId).input('Delivery',sql.Int,req.params.id).query('SELECT l.*,h.WhId,h.DeliveryId,h.CategoryCode,h.Status AS DeliveryStatus,r.ReturnNo FROM dbWMS.dbo.CustomerDeliveryReturnLines l WITH(UPDLOCK,HOLDLOCK) JOIN dbWMS.dbo.CustomerDeliveryReturns r ON r.ReturnId=l.ReturnId JOIN dbWMS.dbo.DeliveryOrders h ON h.DeliveryId=r.DeliveryId WHERE l.ReturnLineId=@ReturnLine AND h.DeliveryId=@Delivery')).recordset[0];if(!item)fail(404,'ไม่พบรายการคืนสินค้า');if(item.PutawayAt)fail(409,'รายการนี้จัดเก็บแล้ว');if(!item.PhysicalReturned||!item.ReceiptLocationCode)fail(409,'รายการนี้ไม่มีสินค้ากลับเข้าคลังให้ย้าย');if(!shipping.can(req,item.CategoryCode,'CONFIRM'))fail(403,'ไม่มีสิทธิ์จัดเก็บสินค้ากลุ่มนี้');
 const canTransferDamage=req.navigation?.user.Role==='ADMIN'||require('../middleware/navigation').hasAction(req.navigation.profile,req.navigation.mode,'TRANSFER','CONFIRM');if(item.CaseType==='DAMAGED'&&!canTransferDamage)fail(403,'การกักกันสินค้า DAMAGE ต้องมีสิทธิ์ TRANSFER');const allowedZones=item.CaseType==='DAMAGED'?['DAMAGE']:['A','B','STORAGE'];const targets=(await q().input('Wh',sql.Int,item.WhId).input('Loc',sql.NVarChar(50),destination).query("SELECT LocationCode,Zone FROM dbMaster.dbo.Locations WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND LocationCode=@Loc AND IsActive=1 AND UPPER(Zone) IN('A','B','STORAGE','DAMAGE')")).recordset[0];if(!targets||!allowedZones.includes(String(targets.Zone).toUpperCase()))fail(400,item.CaseType==='DAMAGED'?'สินค้าชำรุดต้องย้ายเข้า Location โซน DAMAGE':'สินค้าปกติต้องย้ายไปโซน A/B/STORAGE');const category=(await q().input('P',sql.Int,item.ProductId).query('SELECT c.CategoryId,p.Barcode FROM dbMaster.dbo.tblProducts p JOIN dbMaster.dbo.tblCategories c ON c.CategoryId=p.CategoryId WHERE p.ProductId=@P')).recordset[0],rules=(await q().input('Wh',sql.Int,item.WhId).input('Loc',sql.NVarChar(50),destination).query('SELECT CategoryId FROM dbMaster.dbo.tblLocationCategoryRules WHERE WhId=@Wh AND LocationCode=@Loc')).recordset;if(rules.length&&!rules.some(x=>x.CategoryId===category.CategoryId))fail(409,'Location นี้ไม่รองรับกลุ่มสินค้านี้');if(String(targets.Zone).toUpperCase()==='DAMAGE')await require('../services/damage-locations').authorize(q,req);
 const stock=(await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Loc',sql.NVarChar(50),item.ReceiptLocationCode).query('SELECT StockId,Quantity FROM dbWMS.dbo.tblStock WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND ProductId=@P AND LocationCode=@Loc')).recordset[0];if(!stock||Number(stock.Quantity)+0.000001<Number(item.Quantity))fail(409,'ยอดใน RCV ไม่พอจัดเก็บ');const target=(await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Loc',sql.NVarChar(50),destination).query('SELECT StockId,Quantity FROM dbWMS.dbo.tblStock WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND ProductId=@P AND LocationCode=@Loc')).recordset[0],before=Number(target?.Quantity||0);
 await q().input('Id',sql.Int,stock.StockId).input('Q',sql.Decimal(18,2),item.Quantity).query('UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity-@Q,UpdatedAt=SYSDATETIME() WHERE StockId=@Id');if(target)await q().input('Id',sql.Int,target.StockId).input('Q',sql.Decimal(18,2),item.Quantity).query('UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity+@Q,UpdatedAt=SYSDATETIME() WHERE StockId=@Id');else await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Barcode',sql.NVarChar(50),category.Barcode).input('Loc',sql.NVarChar(50),destination).input('Q',sql.Decimal(18,2),item.Quantity).query('INSERT INTO dbWMS.dbo.tblStock(whid,ProductId,Barcode,LocationCode,Quantity) VALUES(@Wh,@P,@Barcode,@Loc,@Q)');
 for(const [location,change,after] of [[item.ReceiptLocationCode,-Number(item.Quantity),Number(stock.Quantity)-Number(item.Quantity)],[destination,Number(item.Quantity),before+Number(item.Quantity)]])await q().input('Wh',sql.Int,item.WhId).input('P',sql.Int,item.ProductId).input('Barcode',sql.NVarChar(50),category.Barcode).input('Loc',sql.NVarChar(50),location).input('Change',sql.Decimal(18,2),change).input('After',sql.Decimal(18,2),after).input('Ref',sql.NVarChar(60),item.ReturnNo).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query("INSERT INTO dbWMS.dbo.tblStockTransactions(TransType,whid,ProductId,Barcode,LocationCode,QtyChange,QtyAfter,RefDocNo,Remark,CreatedBy,CreatedAt) VALUES(N'RETURN_PUTAWAY',@Wh,@P,@Barcode,@Loc,@Change,@After,@Ref,N'จัดเก็บสินค้าคืนจาก RCV',@By,SYSDATETIME())");
 await q().input('Id',sql.Int,item.ReturnLineId).input('Loc',sql.NVarChar(50),destination).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query('UPDATE dbWMS.dbo.CustomerDeliveryReturnLines SET PutawayLocationCode=@Loc,PutawayAt=SYSDATETIME(),PutawayBy=@By WHERE ReturnLineId=@Id');await shipping.audit(q,item.DeliveryId,'RETURN_PUTAWAY',req.user.username||req.user.id,{returnLineId:item.ReturnLineId,returnNo:item.ReturnNo,productCode:item.ProductCode,source:item.ReceiptLocationCode,destination,quantity:Number(item.Quantity)});await tx.commit();res.json({success:true});
}catch(e){if(tx)try{await tx.rollback()}catch{}if(e.number===51000)e.status=409;error(res,e)}});

router.post('/:id/return',async(req,res)=>{let tx;try{
 if(!/^\d+$/.test(req.params.id))fail(400,'เลขใบส่งไม่ถูกต้อง');
 const b=req.body||{},lineId=Number(b.lineId),quantity=Number(b.quantity),source=String(b.sourceLocation||''),destination=String(b.destinationLocation||'');
 if(!Number.isSafeInteger(lineId)||lineId<1||!source||source.length>50||!destination||destination.length>50||!Number.isFinite(quantity)||quantity<=0)fail(400,'ข้อมูล SKU, Location และจำนวนไม่ถูกต้อง');
 const p=await poolPromise,initial=(await p.request().input('Id',sql.Int,req.params.id).query('SELECT WhId FROM dbWMS.dbo.DeliveryOrders WHERE DeliveryId=@Id')).recordset[0];
 if(!initial)fail(404,'ไม่พบใบส่ง');
 tx=new sql.Transaction(p);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);const rq=()=>new sql.Request(tx);
 await rq().input('Wh',sql.Int,initial.WhId).query('SELECT whid FROM dbMaster.dbo.tblWH WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh');
 const order=(await rq().input('Id',sql.Int,req.params.id).query('SELECT * FROM dbWMS.dbo.DeliveryOrders WITH(UPDLOCK,HOLDLOCK) WHERE DeliveryId=@Id')).recordset[0];
 if(!order||order.Status!=='CANCELLED'||!order.Prepared)fail(409,'คืนสินค้าได้เฉพาะใบส่งที่ยกเลิกและเคยเตรียม OUT แล้ว');
 if(!shipping.can(req,order.CategoryCode,'EDIT'))fail(403,'ไม่มีสิทธิ์คืนสินค้ากลุ่มนี้');
 const line=(await rq().input('D',sql.Int,order.DeliveryId).input('Line',sql.Int,lineId).query('SELECT LineId,ProductId,LocationCode,OriginLocationCode,Quantity,ProductCode,ProductName,UOM FROM dbWMS.dbo.DeliveryLines WITH(UPDLOCK,HOLDLOCK) WHERE DeliveryId=@D AND LineId=@Line')).recordset[0];
 if(!line)fail(404,'ไม่พบ SKU ในใบส่งนี้');
 if(line.LocationCode!==source||source===destination||Math.abs(Number(line.Quantity)-quantity)>0.005)fail(409,'ตำแหน่งหรือจำนวนไม่ตรงกับรายการใบส่ง');
 const locations=(await rq().input('Wh',sql.Int,order.WhId).input('From',sql.NVarChar(50),source).input('To',sql.NVarChar(50),destination).query('SELECT LocationCode,Zone FROM dbMaster.dbo.Locations WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND IsActive=1 AND LocationCode IN(@From,@To)')).recordset;
 const from=locations.find(location=>location.LocationCode===source),to=locations.find(location=>location.LocationCode===destination);
 if(!from||String(from.Zone).toUpperCase()!=='OUT')fail(409,'ตำแหน่งต้นทางต้องเป็น OUT ของคลังใบส่ง');
 if(!to||!['A','B','STORAGE'].includes(String(to.Zone).toUpperCase()))fail(400,'เลือก Location ปลายทางในโซน A / B / STORAGE');
 const returned=(await rq().input('Ref',sql.NVarChar(60),order.DeliveryNo).input('Product',sql.Int,line.ProductId).query("SELECT COALESCE(SUM(QtyChange),0) AS Quantity FROM dbWMS.dbo.tblStockTransactions WITH(UPDLOCK,HOLDLOCK) WHERE RefDocNo=@Ref AND ProductId=@Product AND TransType='SHIP_CANCEL' AND QtyChange>0")).recordset[0].Quantity;
 if(Number(returned)+0.005>=Number(line.Quantity))fail(409,'รายการนี้คืนสินค้าแล้ว');
 if(Number(returned)>0)fail(409,'รายการนี้คืนบางส่วนแล้ว กรุณาตรวจสอบประวัติสต๊อกก่อนทำต่อ');
 const stock=(await rq().input('Wh',sql.Int,order.WhId).input('P',sql.Int,line.ProductId).input('L',sql.NVarChar(50),source).query('SELECT Quantity FROM dbWMS.dbo.tblStock WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND ProductId=@P AND LocationCode=@L')).recordset[0];
 if(!stock||Number(stock.Quantity)+0.000001<Number(line.Quantity))fail(409,'ยอดที่ OUT ไม่พอคืน กรุณาตรวจสอบสต๊อกก่อน');
  const reservations=(await rq().input('Wh',sql.Int,order.WhId).input('P',sql.Int,line.ProductId).input('L',sql.NVarChar(50),source).query("SELECT h.DeliveryNo,SUM(l.Quantity) AS ReservedQuantity FROM dbWMS.dbo.DeliveryOrders h WITH(UPDLOCK,HOLDLOCK) JOIN dbWMS.dbo.DeliveryLines l WITH(UPDLOCK,HOLDLOCK) ON l.DeliveryId=h.DeliveryId WHERE h.Status='DRAFT' AND h.WhId=@Wh AND l.ProductId=@P AND l.LocationCode=@L GROUP BY h.DeliveryNo")).recordset;
  const reserved=reservations.reduce((sum,row)=>sum+Number(row.ReservedQuantity||0),0),returnable=Math.max(0,Number(stock.Quantity)-reserved);
if(Number(line.Quantity)>returnable+0.000001){const docs=reservations.map(row=>row.DeliveryNo+' ('+Number(row.ReservedQuantity)+' '+(line.UOM||'หน่วย')+')').join(', ');const fmt=value=>Number(value).toLocaleString('th-TH',{maximumFractionDigits:2});const message=`คืนไม่ได้: ที่ ${source} มี ${fmt(stock.Quantity)} ${line.UOM||'หน่วย'} และใบส่งร่างอื่นจอง ${fmt(reserved)} ${line.UOM||'หน่วย'}${docs?' · '+docs:''} จึงเหลือคืนได้ ${fmt(returnable)} ${line.UOM||'หน่วย'}`;fail(409,message);}
 await rq().input('Wh',sql.Int,order.WhId).input('P',sql.Int,line.ProductId).input('From',sql.NVarChar(50),source).input('To',sql.NVarChar(50),destination).input('Q',sql.Decimal(18,2),line.Quantity).input('Ref',sql.NVarChar(60),order.DeliveryNo).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query("UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity-@Q,UpdatedAt=SYSDATETIME() WHERE whid=@Wh AND ProductId=@P AND LocationCode=@From;IF EXISTS(SELECT 1 FROM dbWMS.dbo.tblStock WHERE whid=@Wh AND ProductId=@P AND LocationCode=@To) UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity+@Q,UpdatedAt=SYSDATETIME() WHERE whid=@Wh AND ProductId=@P AND LocationCode=@To;ELSE INSERT INTO dbWMS.dbo.tblStock(whid,ProductId,LocationCode,Quantity) VALUES(@Wh,@P,@To,@Q);INSERT INTO dbWMS.dbo.tblStockTransactions(TransType,whid,ProductId,LocationCode,QtyChange,QtyAfter,RefDocNo,Remark,CreatedBy,CreatedAt) SELECT 'SHIP_CANCEL',@Wh,@P,LocationCode,CASE WHEN LocationCode=@From THEN -@Q ELSE @Q END,Quantity,@Ref,N'ยืนยันคืนสินค้าไปยัง Location',@By,SYSDATETIME() FROM dbWMS.dbo.tblStock WHERE whid=@Wh AND ProductId=@P AND LocationCode IN(@From,@To)");
 await rq().input('To',sql.NVarChar(50),destination).input('Line',sql.Int,lineId).query('UPDATE dbWMS.dbo.DeliveryLines SET LocationCode=@To WHERE LineId=@Line');
 await shipping.audit(rq,order.DeliveryId,'RETURN',req.user.username||req.user.id,{lineId,productCode:line.ProductCode,source,destination,quantity:Number(line.Quantity)});
 await tx.commit();res.json({success:true,returned:true});
 }catch(e){if(tx)try{await tx.rollback()}catch{}if(e.number===51000)e.status=409;error(res,e)}});
router.post('/:id/:action',async(req,res)=>{let tx;try{if(!/^\d+$/.test(req.params.id)||!['dispatch','cancel','receive','prepare'].includes(req.params.action))fail(400,'คำสั่งไม่ถูกต้อง');const b=req.body||{},action=req.params.action,p=await poolPromise;const initial=(await p.request().input('Id',sql.Int,req.params.id).query('SELECT WhId,DestinationWhId FROM dbWMS.dbo.DeliveryOrders WHERE DeliveryId=@Id')).recordset[0];if(!initial)fail(404,'ไม่พบใบส่ง');tx=new sql.Transaction(p);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);const rq=()=>new sql.Request(tx);for(const wh of [...new Set([initial.WhId,initial.DestinationWhId].filter(Boolean))].sort((a,b)=>a-b))await rq().input('Wh',sql.Int,wh).query('SELECT whid FROM dbMaster.dbo.tblWH WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh');const order=(await rq().input('Id',sql.Int,req.params.id).query('SELECT * FROM dbWMS.dbo.DeliveryOrders WITH(UPDLOCK,HOLDLOCK) WHERE DeliveryId=@Id')).recordset[0];if(!shipping.can(req,order.CategoryCode,action==='cancel'?'EDIT':'CONFIRM'))fail(403,'ไม่มีสิทธิ์ทำรายการขนส่งกลุ่มนี้');if(['prepare','dispatch'].includes(action)&&order.Status==='DRAFT'){const clinicLines=(await rq().input('ClinicOrder',sql.Int,order.DeliveryId).query('SELECT ProductId FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@ClinicOrder')).recordset;await require('../services/product-clinic').check(rq,order.DeliveryType,clinicLines.map(l=>l.ProductId));}if(action==='prepare')await shipping.prepare(rq,order,b,String(req.user.username||req.user.id).slice(0,50));if((action==='dispatch'&&['SENT','RECEIVED'].includes(order.Status))||(action==='cancel'&&order.Status==='CANCELLED')||(action==='receive'&&order.Status==='RECEIVED')){await tx.commit();return res.json({success:true,duplicate:true})}
if(action==='cancel'){if(order.Status!=='DRAFT')fail(409,'ยกเลิกได้เฉพาะร่างที่ยังไม่ส่ง');await rq().input('Id',sql.Int,order.DeliveryId).query("UPDATE dbWMS.dbo.DeliveryOrders SET Status='CANCELLED' WHERE DeliveryId=@Id");await shipping.undoPrepare(rq,order,String(req.user.username||req.user.id));}
if(action==='receive'){if(order.DeliveryType==='WAREHOUSE')await shipping.receiveWarehouse(rq,order,b,String(req.user.username||req.user.id));if(order.Status!=='SENT')fail(409,'ต้องส่งสินค้าก่อน');if(typeof b.receivedBy!=='string'||!b.receivedBy.trim()||b.receivedBy.length>100)fail(400,'ระบุชื่อผู้รับปลายทาง');await rq().input('Id',sql.Int,order.DeliveryId).input('By',sql.NVarChar(100),b.receivedBy.trim()).input('Warehouse',sql.Bit,order.DeliveryType==='WAREHOUSE').query("UPDATE dbWMS.dbo.DeliveryOrders SET Status='RECEIVED',ReceivedBy=@By,ReceivedAt=SYSDATETIME() WHERE DeliveryId=@Id;UPDATE dbWMS.dbo.DeliveryCustody SET Status=CASE WHEN @Warehouse=1 THEN 'RECEIVED_STOCK' ELSE 'AT_DESTINATION' END,ReceivedAt=SYSDATETIME() WHERE LineId IN(SELECT LineId FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@Id)");}
if(action==='dispatch'){if(!order.Prepared)fail(409,'ต้องเตรียมสินค้าไป OUT ก่อนส่ง');if(order.Status!=='DRAFT')fail(409,'ใบส่งไม่อยู่ในสถานะร่าง');let carrier;if(order.DeliveryType==='CLINIC'){if(b.checked!==true||typeof b.handoverTo!=='string'||!b.handoverTo.trim()||b.handoverTo.length>100||typeof b.handoverNote!=='string'||b.handoverNote.length>500)fail(400,'ระบุผู้รับมอบและยืนยันตรวจสินค้าให้ครบ');carrier={tranid:null};b.carrier='ส่งมอบคลินิกโดยตรง';b.trackingNo='';b.vehicleNo='';b.cartons=null;await rq().input('D',sql.Int,order.DeliveryId).input('To',sql.NVarChar(100),b.handoverTo.trim()).input('Note',sql.NVarChar(500),b.handoverNote.trim()||null).query("UPDATE dbWMS.dbo.DeliveryOrders SET HandoverTo=@To,HandoverNote=@Note,DispatchMethod='CLINIC_HANDOVER' WHERE DeliveryId=@D");}else{const choices=await shipping.carriers(rq,(await rq().input('D',sql.Int,order.DeliveryId).query('SELECT ProductId FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@D')).recordset.map(l=>l.ProductId));carrier=choices.find(c=>c.tranid===b.carrierCode);if(!carrier||b.checked!==true)fail(400,'เลือกผู้ขนส่งที่รองรับสินค้าครบทุกรายการและยืนยันตรวจขึ้นรถ');b.carrier=carrier.tranName.slice(0,100);if(typeof b.carrier!=='string'||!b.carrier.trim()||b.carrier.length>100||typeof b.trackingNo!=='string'||b.trackingNo.length>100||typeof b.vehicleNo!=='string'||b.vehicleNo.length>30||!Number.isInteger(b.cartons)||b.cartons<=0||b.cartons>1000000)fail(400,'ระบุขนส่งและจำนวนกล่องให้ถูกต้อง');}const lines=(await rq().input('Id',sql.Int,order.DeliveryId).query('SELECT * FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@Id ORDER BY ProductId,LocationCode')).recordset;await rq().input('D',sql.Int,order.DeliveryId).input('C',sql.NVarChar(30),carrier.tranid).query("UPDATE dbWMS.dbo.DeliveryOrders SET Status='SENT',CarrierCode=@C WHERE DeliveryId=@D");await shipping.dispatchContainers(rq,order,String(req.user.username||req.user.id));for(const l of lines){const r=await rq().input('Wh',sql.Int,order.WhId).input('Product',sql.Int,l.ProductId).input('Loc',sql.NVarChar(50),l.LocationCode).input('Qty',sql.Decimal(18,2),l.Quantity).input('Ref',sql.NVarChar(60),order.DeliveryNo).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query(`DECLARE @Old DECIMAL(18,2),@Barcode NVARCHAR(50);SELECT @Old=Quantity FROM dbWMS.dbo.tblStock WITH(UPDLOCK,HOLDLOCK) WHERE whid=@Wh AND ProductId=@Product AND LocationCode=@Loc;IF @Old IS NULL OR @Old<@Qty THROW 51000,N'ยอด OUT ไม่พอ ห้ามส่ง',1;SELECT @Barcode=Barcode FROM dbMaster.dbo.tblProducts WHERE ProductId=@Product;UPDATE dbWMS.dbo.tblStock SET Quantity=Quantity-@Qty,UpdatedAt=SYSDATETIME() WHERE whid=@Wh AND ProductId=@Product AND LocationCode=@Loc;INSERT INTO dbWMS.dbo.tblStockTransactions(TransType,whid,ProductId,Barcode,LocationCode,QtyChange,QtyAfter,RefDocNo,Remark,CreatedBy,CreatedAt) VALUES(N'LOAD',@Wh,@Product,@Barcode,@Loc,-@Qty,@Old-@Qty,@Ref,N'ยืนยันส่งจริง',@By,SYSDATETIME());`);if(order.Ownership==='COMPANY'&&order.DeliveryType!=='CLINIC')await rq().input('Line',sql.Int,l.LineId).input('Qty',sql.Decimal(18,2),l.Quantity).query("INSERT INTO dbWMS.dbo.DeliveryCustody(LineId,Quantity,Status) VALUES(@Line,@Qty,'IN_TRANSIT')")}
await rq().input('Id',sql.Int,order.DeliveryId).input('Carrier',sql.NVarChar(100),b.carrier.trim()).input('Tracking',sql.NVarChar(100),b.trackingNo.trim()).input('Vehicle',sql.NVarChar(30),b.vehicleNo.trim()).input('Cartons',sql.Int,b.cartons).input('By',sql.NVarChar(50),String(req.user.username||req.user.id).slice(0,50)).query("UPDATE dbWMS.dbo.DeliveryOrders SET Status='SENT',Carrier=@Carrier,TrackingNo=@Tracking,VehicleNo=@Vehicle,Cartons=@Cartons,SentBy=@By,SentAt=SYSDATETIME() WHERE DeliveryId=@Id");}
await shipping.audit(rq,order.DeliveryId,action.toUpperCase(),req.user.username||req.user.id,b);await tx.commit();res.json({success:true});}catch(e){if(tx)try{await tx.rollback()}catch{}if(e.number===51000)e.status=409;error(res,e)}});

router.get('/:id/pdf',async(req,res)=>{try{
 if(!/^\d+$/.test(req.params.id))fail(400,'เลขใบส่งไม่ถูกต้อง');
 const pool=await poolPromise;
 const result=await pool.request().input('Id',sql.Int,req.params.id).query('SELECT * FROM dbWMS.dbo.DeliveryOrders WHERE DeliveryId=@Id;SELECT * FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@Id ORDER BY LineId');
 if(!result.recordsets[0].length)fail(404,'ไม่พบใบส่ง');
 const order=result.recordsets[0][0];if(!shipping.can(req,order.CategoryCode,'EXPORT'))fail(403,'ไม่มีสิทธิ์ส่งออกกลุ่มนี้');
 const {createDeliveryPdf}=require('../services/delivery-pdf');
 const pdf=await createDeliveryPdf(order,result.recordsets[1]);
 const filename=String(order.DeliveryNo).replace(/[^A-Za-z0-9_-]/g,'_')+'.pdf';
 res.set({'Content-Type':'application/pdf','Content-Disposition':'attachment; filename="'+filename+'"','Cache-Control':'no-store','Content-Length':String(pdf.length)}).send(pdf);
}catch(e){error(res,e)}});

router.get('/:id/carriers',async(req,res)=>{try{const p=await poolPromise,q=()=>p.request(),d=(await q().input('D',sql.Int,req.params.id).query('SELECT CategoryCode FROM dbWMS.dbo.DeliveryOrders WHERE DeliveryId=@D;SELECT ProductId FROM dbWMS.dbo.DeliveryLines WHERE DeliveryId=@D')).recordsets;if(!d[0][0]||!shipping.can(req,d[0][0].CategoryCode))fail(403,'ไม่มีสิทธิ์');res.json({success:true,data:await shipping.carriers(q,d[1].map(l=>l.ProductId)),outLocations:(await q().input('D',sql.Int,req.params.id).query("SELECT l.LocationCode FROM dbMaster.dbo.Locations l JOIN dbWMS.dbo.DeliveryOrders h ON h.WhId=l.whid WHERE h.DeliveryId=@D AND l.IsActive=1 AND UPPER(l.Zone)='OUT'")).recordset})}catch(e){error(res,e)}});
router.get('/:id/receipt-locations',async(req,res)=>{try{if(!/^[1-9]\d*$/.test(req.params.id))fail(400,'รหัสใบส่งไม่ถูกต้อง');const p=await poolPromise,o=(await p.request().input('D',sql.Int,req.params.id).query('SELECT * FROM dbWMS.dbo.DeliveryOrders WHERE DeliveryId=@D')).recordset[0];if(!o||!shipping.can(req,o.CategoryCode,'CONFIRM'))fail(403,'ไม่มีสิทธิ์รับกลุ่มนี้');res.json({success:true,destinationWhId:o.DestinationWhId,locations:o.DeliveryType==='WAREHOUSE'?(await p.request().input('W',sql.Int,o.DestinationWhId).query("SELECT LocationCode FROM dbMaster.dbo.Locations WHERE whid=@W AND IsActive=1 AND UPPER(Zone)='RCV'")).recordset:[]})}catch(e){error(res,e)}});
router.get('/rm/containers',async(req,res)=>{try{if(!shipping.can(req,'RM'))fail(403,'ไม่มีสิทธิ์ RM');res.json({success:true,data:(await(await poolPromise).request().query("SELECT c.* FROM dbWMS.dbo.RMContainers c WHERE RemainingBase>0 AND (ExpiryDate IS NULL OR ExpiryDate>=CONVERT(date,GETDATE())) AND NOT EXISTS(SELECT 1 FROM dbWMS.dbo.DeliveryContainers dc JOIN dbWMS.dbo.DeliveryOrders h ON h.DeliveryId=dc.DeliveryId WHERE dc.ContainerId=c.ContainerId AND h.Status='DRAFT')")).recordset})}catch(e){error(res,e)}});module.exports=router;
